package com.madhukar.upisplitter;
import com.madhukar.upisplitter.model.User; import com.madhukar.upisplitter.repository.UserRepository; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.password.PasswordEncoder; import java.time.Instant;
@SpringBootApplication public class UpiSplitterApplication {public static void main(String[] args){SpringApplication.run(UpiSplitterApplication.class,args);} @Bean CommandLineRunner seed(UserRepository repo,PasswordEncoder encoder){return args->{if(repo.findByEmailIgnoreCase("demo@example.com").isEmpty()){repo.save(User.builder().name("Demo User").email("demo@example.com").passwordHash(encoder.encode("Demo@12345")).role(User.Role.USER).createdAt(Instant.now()).updatedAt(Instant.now()).build());}if(repo.findByEmailIgnoreCase("admin@example.com").isEmpty()){repo.save(User.builder().name("Admin").email("admin@example.com").passwordHash(encoder.encode("Admin@12345")).role(User.Role.ADMIN).createdAt(Instant.now()).updatedAt(Instant.now()).build());}};}}
